import{j as e}from"./motion-Ciz4_8MT.js";import{L as r}from"./react-vendor-glTYHxko.js";import{A as n}from"./AnimatedSection-B9HHPnX-.js";import{C as i}from"./calendar-D5dhTXBS.js";import{A as s}from"./arrow-right-BHkLDvrv.js";function u({blog:t,index:o=0,big:a=!1}){return e.jsx(n,{direction:"up",delay:o*.05,children:e.jsxs(r,{to:`/blog/${t.id}`,className:`group flex h-full flex-col overflow-hidden rounded-3xl bg-white shadow-soft transition-all duration-300 hover:-translate-y-1.5 hover:shadow-card ${a?"lg:flex-row":""}`,children:[e.jsxs("div",{className:`relative overflow-hidden ${a?"lg:w-1/2":""} ${a?"lg:h-auto":"h-52"}`,children:[e.jsx("img",{src:t.image,alt:t.title,loading:"lazy",className:`w-full object-cover transition-transform duration-500 group-hover:scale-105 ${a?"h-56 lg:h-full":"h-52"}`}),e.jsx("span",{className:"absolute left-4 top-4 rounded-full bg-forest/90 px-3 py-1 text-xs font-bold text-white backdrop-blur",children:t.category})]}),e.jsxs("div",{className:`flex flex-1 flex-col ${a?"lg:w-1/2":""} p-6`,children:[e.jsxs("div",{className:"flex items-center gap-2 text-xs text-charcoal-muted",children:[e.jsx(i,{size:13}),new Date(t.date).toLocaleDateString("en-US",{day:"numeric",month:"short",year:"numeric"}),e.jsx("span",{className:"mx-1",children:"·"}),e.jsx("span",{children:t.readTime})]}),e.jsx("h3",{className:`mt-3 font-bold leading-snug group-hover:text-forest transition-colors ${a?"text-2xl":"text-lg"}`,children:t.title}),e.jsx("p",{className:"mt-2.5 text-sm text-charcoal-muted leading-relaxed flex-1",children:t.excerpt}),e.jsxs("span",{className:"mt-5 inline-flex items-center gap-1.5 text-sm font-bold text-terracotta transition-all duration-300 group-hover:gap-3",children:["Read Story",e.jsx(s,{size:16})]})]})]})})}const p=[{id:"new-beginning",title:"A New Beginning: How Aanya Found Her Home at HopeCare",category:"Stories",excerpt:"When Aanya arrived at HopeCare, she was shy and withdrawn. Today, she is one of our most confident students, dreaming of becoming a doctor.",date:"2026-08-18",author:"Priya Sharma",authorRole:"Child Care Coordinator",featured:!0,readTime:"5 min read",image:"https://images.unsplash.com/photo-1509099836639-18ba1795216d?w=900&h=600&fit=crop",body:[{type:"p",content:"When Aanya first walked through our doors, she kept her eyes on the ground and barely spoke a word. At just nine years old, she had experienced more loss than many of us do in a lifetime. She arrived with a small bag of belongings and a heart heavy with uncertainty."},{type:"h2",content:"Finding Her Voice"},{type:"p",content:"Our care team approached Aanya with patience and warmth. We never rushed her. Her room was made cozy, her meals were prepared carefully, and slowly, she began to feel safe. Within weeks, she was joining group activities and making her first friends."},{type:"p",content:"Sita, one of our counselors, remembers the moment Aanya first smiled. “It was during an art session. She painted a bright yellow sun and said, ‘This is what home feels like now.’ I knew then that she was going to be okay.”"},{type:"h2",content:"Dreaming Again"},{type:"p",content:"Today, Aanya is one of the top students in her class. She loves science and dreams of becoming a doctor. She has joined our computer training program and participates in every cultural event with enthusiasm."},{type:"p",content:"Her journey is a reminder that with love, patience, and support, every child has the power to rewrite their story. Aanya is no longer the quiet girl at the back of the room. She is a leader, a dreamer, and a testament to the power of hope."}]},{id:"learning-to-dream-again",title:"Learning to Dream Again: Supporting Our Seniors",category:"Elderly Care",excerpt:"For 78-year-old Mr. Raghavan, HopeCare became more than a home - it became a place to find purpose again.",date:"2026-07-22",author:"Arjun Mehta",authorRole:"Senior Care Coordinator",featured:!1,readTime:"4 min read",image:"https://images.unsplash.com/photo-1581833971358-2c8b550f87b3?w=900&h=600&fit=crop",body:[{type:"p",content:"Mr. Raghavan taught mathematics for over 40 years. When he lost his wife and his children moved abroad, the silence of his home became overwhelming. He felt invisible, purposeless, alone."},{type:"h2",content:"A Community of Care"},{type:"p",content:"At HopeCare, Mr. Raghavan found something he had lost: community. Our residents share meals, stories, and laughter. He now teaches a small math class to our children every Saturday, a role that fills him with purpose."},{type:"p",content:"“The children call me ‘Master Ji,’” he says with a warm smile. “They remind me that I still have so much to give. I may have lost my own family, but I gained a much bigger one here.”"},{type:"h2",content:"Dignity in Every Day"},{type:"p",content:"We believe every senior deserves to live with dignity, respect, and purpose. Through companionship, quality healthcare, and meaningful activities, we help our senior residents rediscover joy in each new day."}]},{id:"finding-family-new-home",title:"Finding Family in a New Home",category:"Stories",excerpt:"How our intergenerational program brings children and seniors together in a bond like no other.",date:"2026-06-10",author:"Neha Gupta",authorRole:"Program Director",featured:!1,readTime:"6 min read",image:"https://images.unsplash.com/photo-1511632765486-a01980e01a18?w=900&h=600&fit=crop",body:[{type:"p",content:"There is something magical about watching an eight-year-old and an eighty-year-old share a moment. Our intergenerational program brings children and senior residents together for storytime, gardening, music, and shared meals."},{type:"h2",content:"Bonds That Heal"},{type:"p",content:"For the children, these relationships provide a sense of family and stability many have never known. For the seniors, they offer purpose, warmth, and the joy of being needed again."},{type:"p",content:"Grandmother Lakshmi, 82, reads bedtime stories to the younger children every evening. “I always dreamed of being a grandmother,” she shares. “Here, I am a grandmother to thirty grandchildren.”"},{type:"h2",content:"The Heart of HopeCare"},{type:"p",content:"Our home is built on the belief that everyone deserves to belong. When generations come together, everyone grows. The children learn wisdom; the seniors rediscover youth. And together, we become family."}]},{id:"power-of-volunteering",title:"The Power of Giving Time: Stories from Our Volunteers",category:"Volunteering",excerpt:"Volunteers are the heartbeat of HopeCare. Read how ordinary people are doing extraordinary things.",date:"2026-05-28",author:"Kavita Rao",authorRole:"Volunteer Coordinator",featured:!1,readTime:"4 min read",image:"https://images.unsplash.com/photo-1544027993-37dbfe43562a?w=900&h=600&fit=crop",body:[{type:"p",content:"Every Saturday, Rohan leaves his job early and drives an hour to volunteer at HopeCare. He teaches coding to our older children. “I don’t have much money to give,” he says, “but I have this skill, and someone here needs it.”"},{type:"h2",content:"A Small Act, A Big Difference"},{type:"p",content:"Whether it’s reading to our seniors, helping with schoolwork, gardening, or organizing events, our volunteers bring energy and love that money simply cannot buy."},{type:"p",content:"Our volunteer program has grown to over 95 active volunteers, each contributing their unique time, skills, and heart to our community."},{type:"h2",content:"Join Us"},{type:"p",content:"If you have an hour, a day, or a skill, we would love to have you. Your presence can make a meaningful difference in someone’s life."}]},{id:"healthy-eating-journey",title:"Healthy Eating: Nourishing Bodies and Dreams",category:"Community",excerpt:"Inside our kitchen where every meal is crafted with care, nutrition, and a whole lot of love.",date:"2026-04-15",author:"Dr. Meera Nair",authorRole:"Nutritionist",featured:!1,readTime:"5 min read",image:"https://images.unsplash.com/photo-1498837167922-ddd27525d352?w=900&h=600&fit=crop",body:[{type:"p",content:"Nutrition is the foundation of everything we do. A well-nourished child can focus better in class, play harder, and grow stronger. A well-nourished senior experiences better health and vitality."},{type:"h2",content:"Our Kitchen"},{type:"p",content:"Every day, our kitchen prepares over 500 balanced meals. Our menus are designed by nutritionists to meet the specific needs of growing children and aging seniors."},{type:"p",content:"We prioritize fresh, locally-sourced ingredients and accommodate special dietary needs with care. Good food is a form of love, and our kitchen is full of it."}]},{id:"mental-health-matters",title:"Why Emotional Support Matters As Much As Healthcare",category:"Child Care",excerpt:"Healing is not just about medicine. Discover our holistic approach to emotional well-being.",date:"2026-03-08",author:"Dr. Sanjay Kumar",authorRole:"Counseling Lead",featured:!1,readTime:"5 min read",image:"https://images.unsplash.com/photo-1573497019940-1c28c88b4f3e?w=900&h=600&fit=crop",body:[{type:"p",content:"Many children arrive at HopeCare carrying emotional wounds that no amount of food or shelter alone can heal. That is why emotional support is at the core of everything we do."},{type:"h2",content:"A Safe Space to Heal"},{type:"p",content:"Our trained counselors provide individual and group therapy sessions, creating safe spaces where residents can express their feelings and begin to heal."},{type:"p",content:"We integrate art therapy, music, and mindfulness into our programs because emotional healing is a journey, not a destination."}]}],g=["All","Stories","Child Care","Elderly Care","Community","Volunteering","Fundraising","Education"];export{u as B,g as a,p as b};
